// ============================ CONFIG — edit for your site ============================
const SITE = {
  site_url: 'https://your-site.com',            // your WordPress URL, no trailing slash
  brand_name: 'Your Brand',
  brand_description: 'a studio that builds automation and AI solutions for small businesses',
  audience: 'agency owners, SaaS teams, e-commerce operators and developers',
  quote_url: 'https://your-site.com/contact/'   // shown next to every CTA box
};

// One entry per blog category. The writer never writes sales copy — the CTA box below
// is appended automatically by "Prepare Post", so every post ends with a relevant offer.
// wp_category_id: Posts > Categories in WordPress, hover the category, read tag_ID in the URL.
const categories = [
  {
    category: 'Automation', label: 'Workflow Automation', wp_category_id: 1,
    topic_prompt: 'Suggest a specific, practical blog post title about automating a repetitive business process with n8n — forms, spreadsheets, email, CRMs or scheduled reports.',
    image_style: 'abstract workflow nodes connected by glowing lines, gears and document icons, teal and blue accents on dark navy background',
    cta: { title: 'Want this automated for you?', text: 'We design and build n8n workflows around your existing tools, with error handling and documentation included.', url: 'https://your-site.com/services/', button: 'See our services' }
  },
  {
    category: 'AI', label: 'AI Agents & Workflows', wp_category_id: 1,
    topic_prompt: 'Suggest a specific, practical blog post title about using AI agents and LLMs inside business workflows — support triage, document extraction, classification, drafting replies, structured outputs or human-in-the-loop approval.',
    image_style: 'glowing neural network visualization, AI chat bubbles, abstract synaptic connections, purple and cyan gradient glow on dark background',
    cta: { title: 'Need an AI workflow built around your process?', text: 'We build AI agents with structured outputs, validation and human approval steps.', url: 'https://your-site.com/services/', button: 'Talk to us' }
  },
  {
    category: 'Integrations', label: 'API Integration', wp_category_id: 1,
    topic_prompt: 'Suggest a specific, practical blog post title about integrating third-party REST APIs with n8n — authentication, pagination, rate limits, webhooks or retries.',
    image_style: 'API connection diagram with JSON code blocks, two systems connected by data pipes, yellow and cyan on dark background',
    cta: { title: 'Connect your systems without the maintenance burden', text: 'Integrations with your CRM, databases and APIs — with retries, alerting and documentation.', url: 'https://your-site.com/services/', button: 'Custom integrations' }
  },
  {
    category: 'Self-hosting', label: 'Running n8n in Production', wp_category_id: 1,
    topic_prompt: 'Suggest a specific, practical blog post title about running n8n reliably in production — self-hosting, backups, updates, credentials, error workflows or monitoring.',
    image_style: 'server rack with interconnected workflow nodes, shield and backup icons, monitoring graph, teal and blue on dark navy background',
    cta: { title: 'A production-grade n8n setup', text: 'We deploy and harden self-hosted n8n with backups, secure credentials and monitoring.', url: 'https://your-site.com/services/', button: 'n8n setup & support' }
  }
];
// ====================================================================================

// Rotate through all categories before repeating (staticData persists across production runs).
const sd = $getWorkflowStaticData('global');
sd.categoryRotation = sd.categoryRotation || { used: [] };
const keys = categories.map(c => c.category);
sd.categoryRotation.used = sd.categoryRotation.used.filter(x => keys.includes(x));

let unused = categories.filter(c => !sd.categoryRotation.used.includes(c.category));
if (unused.length === 0) { sd.categoryRotation.used = []; unused = categories.slice(); }

const chosen = unused[Math.floor(Math.random() * unused.length)];
sd.categoryRotation.used.push(chosen.category);

return [{ json: Object.assign({}, SITE, chosen) }];

// Collect recently published titles so the topic generator never repeats them.
const decode = (s) => String(s)
  .replace(/<[^>]+>/g, '')
  .replace(/&#8217;|&#039;|&rsquo;/g, "'")
  .replace(/&#8211;|&#8212;|&ndash;|&mdash;/g, '-')
  .replace(/&#8220;|&#8221;|&quot;/g, '"')
  .replace(/&amp;/g, '&')
  .trim();

const titles = $input.all()
  .map(i => (i.json && i.json.title && i.json.title.rendered) ? decode(i.json.title.rendered) : '')
  .filter(Boolean);

return [{ json: { recent_titles: titles, recent_count: titles.length } }];

