// Prepare Brief — flattens topic + generated title + Tavily research into one predictable
// item, so Blog Writer never reads fields from a node that does not have them.
const topic = $('Topic Select').first().json;
const topicNode = $('Generate Topic').first().json;
const search = ($input.first() && $input.first().json) ? $input.first().json : {};

// ------------------------------------------------------------- 1) Title
let title = '';
if (topicNode && topicNode.message && typeof topicNode.message.content === 'string') {
  title = topicNode.message.content;
} else if (typeof topicNode.content === 'string') {
  title = topicNode.content;
}
title = String(title)
  .replace(/^\s*["'“‘]+/, '')
  .replace(/["'”’]+\s*$/, '')
  .replace(/\s+/g, ' ')
  .trim();
if (!title) throw new Error('Prepare Brief: "Generate Topic" returned no usable title.');
if (title.length > 200) title = title.slice(0, 200).trim();

// ---------------------------------------------------------- 2) Research
const results = Array.isArray(search.results) ? search.results : [];
const research = results.slice(0, 6).map((r, i) => {
  const t = String(r.title || '').trim();
  const u = String(r.url || '').trim();
  const c = String(r.content || '').replace(/\s+/g, ' ').trim().slice(0, 700);
  return '[' + (i + 1) + '] ' + t + '\nURL: ' + u + '\n' + c;
}).join('\n\n');

const researchBlock = research ||
  '(No research results were returned. Write from general technical knowledge only. ' +
  'Do NOT invent statistics, benchmarks, version numbers, or cite any source.)';

return [{
  json: {
    title: title,
    category: topic.category,
    label: topic.label,
    wp_category_id: topic.wp_category_id,
    image_style: topic.image_style,
    research: researchBlock,
    research_count: results.length
  }
}];

