// Prepare Post — assembles the final WordPress payload. Reads each source node by name,
// cleans the HTML, appends the category CTA box and fails loudly if the HTML is broken.
const meta = ($('Create Title, Slug, Meta').first().json.output) || {};
const htmlNode = $('Create HTML').first().json || {};
const brief = $('Prepare Brief').first().json;
const site = $('Topic Select').first().json;

// ------------------------------------------------------------- 1) HTML
let content = '';
if (htmlNode.message && typeof htmlNode.message.content === 'string') content = htmlNode.message.content;
else if (typeof htmlNode.output === 'string') content = htmlNode.output;
else if (typeof htmlNode.content === 'string') content = htmlNode.content;

content = String(content)
  .replace(/```[a-zA-Z]*\s*/g, '')
  .replace(/```/g, '')
  .replace(/[“”]/g, '"')
  .replace(/[‘’]/g, "'")
  .replace(/<\/?(?:html|head|body)[^>]*>/gi, '')
  .trim();
const firstTag = content.indexOf('<');
if (firstTag > 0) content = content.slice(firstTag).trim();

if (content.length < 500) throw new Error('Prepare Post: cleaned HTML is only ' + content.length + ' chars — refusing to publish a broken post.');
if (content.indexOf('<') === -1) throw new Error('Prepare Post: content contains no HTML tags.');

// ------------------------------------------------------- 2) Title / slug
const slugify = (s) => String(s)
  .toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
  .slice(0, 60).replace(/-+$/, '');

const title = String(meta.title || brief.title || '').replace(/\s+/g, ' ').trim();
if (!title) throw new Error('Prepare Post: no title available.');
const slug = slugify(meta.slug || title);
if (!slug) throw new Error('Prepare Post: could not derive a slug.');
const meta_description = String(meta.meta_description || '').replace(/\s+/g, ' ').trim().slice(0, 155);
const focus_keyword = String(meta.focus_keyword || '').replace(/\s+/g, ' ').trim();

// ------------------------------------------------- 3) CTA box
const cta = site.cta || null;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
if (cta && cta.url) {
  content += '\n<div class="post-cta" style="margin:40px 0 0;padding:28px 30px;border:1px solid rgba(77,217,232,.45);border-radius:18px;background:rgba(77,217,232,.06)">'
    + '<h3 style="margin-top:0">' + esc(cta.title) + '</h3>'
    + '<p>' + esc(cta.text) + '</p>'
    + '<p><a href="' + esc(cta.url) + '"><strong>' + esc(cta.button) + ' &rarr;</strong></a>'
    + (site.quote_url ? ' &nbsp;&middot;&nbsp; <a href="' + esc(site.quote_url) + '">Request a quote</a>' : '')
    + '</p></div>';
}

return [{
  json: {
    title, slug, meta_description, excerpt: meta_description, focus_keyword, content,
    content_length: content.length,
    wp_category_id: brief.wp_category_id,
    category: brief.category,
    label: brief.label,
    research_count: brief.research_count
  }
}];
